import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-111: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short111', durationInSeconds: 38.95, fps: 30, width: 1080, height: 1920 };



const B1 = secToFrame(3.1);
const B2 = secToFrame(9.9);
const B3 = secToFrame(14.4);
const B4 = secToFrame(21.9);
const B5 = secToFrame(28.3);
const CTA = secToFrame(35.3);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);


const Short111: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-111/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="DEEPSEEK SEARCH" lines={[{ text: 'FREE SEARCH ENDS' }, { text: 'NOVEMBER 1', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Search + Fetch" tagline="Free today." chip="FREE NOW" at={B1 + 4}>
          <Panel>
            <Line k="Via Harness" v="$0" good />
            <Line k="Via Claude Code" v="$0" good />
            <Line k="Via Codex" v="$0" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Billing starts" tagline="Midnight Beijing time." chip="NOV 1" at={B2 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Date" v="Nov 1, 2026" bad />
            <Line k="Time" v="00:00 Beijing" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="The new price" tagline="Each, per request." chip="75¢/1K" at={B3 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Search" v="$0.75 / 1,000" bad />
            <Line k="Fetch" v="$0.75 / 1,000" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Flash tokens" tagline="Still cheap, off-peak." chip="15¢ IN" at={B4 + 4}>
          <Panel>
            <Line k="Input" v="$0.15" good />
            <Line k="Output" v="$0.60" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Second meter" tagline="Agents search all day." chip="CHECK" at={B5 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Tokens" v="metered" />
            <Line k="Search" v="metered from Nov 1" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-111/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="DEEPSEEK SEARCH" lines={[{ text: 'FREE SEARCH ENDS' }, { text: 'NOVEMBER 1', accent: true }]} />
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short111;
